INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Marktumfeld in der IT immer stabil bleibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Es ändert sich durch Trends"}, {"text": "Ja", "correct": false, "because": "Zu statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich das Marktumfeld für eine IT-Firma analysiere?', 3, '[{"text": "Externe Faktoren", "correct": true, "because": "Beeinflussen Markt"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren gehören zum Marktumfeld in der IT?', 5, '[{"text": "Wettbewerber", "correct": true, "because": "Beeinflussen Marktposition"}, {"text": "Technologische Trends", "correct": true, "because": "Formen Angebot"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Marktfaktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Marktumfeld beeinflusst IT-Strategien. b) Es ist immer vorhersehbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unvorhersehbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich das Marktumfeld für eine IT-Firma analysiere?', 4, '[{"text": "Kundentrends", "correct": false, "because": "Beeinflussen Nachfrage"}, {"text": "Wettbewerbsaktionen", "correct": false, "because": "Zeigen Markt"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Marktumfeld nur lokale Faktoren umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch globale Einflüsse"}, {"text": "Ya", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich das Marktumfeld in der IT analysiere?', 3, '[{"text": "Risiken erkennen", "correct": true, "because": "Passt Strategie an"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prägen das Marktumfeld in der IT?', 5, '[{"text": "Wirtschaftslage", "correct": true, "because": "Beeinflusst Nachfrage"}, {"text": "Regulierungen", "correct": true, "because": "Setzen Rahmen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Marktumfeld umfasst Wettbewerber. b) Es ist immer kontrollierbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht kontrollierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um das Marktumfeld für eine IT-Firma zu analysieren?', 4, '[{"text": "Marktdaten", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Trendberichte", "correct": false, "because": "Zeigen Entwicklungen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Marktumfeld in der IT immer global?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal relevant"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Analyse des Marktumfelds?', 4, '[{"text": "Strategische Anpassung", "correct": true, "because": "Reagiert auf Trends"}, {"text": "Risikominimierung", "correct": true, "because": "Vermeidet Fehler"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Marktumfeld nur für Hardware relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software/Dienste"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um das Marktumfeld einer IT-Firma zu analysieren?', 3, '[{"text": "Marktberichte", "correct": true, "because": "Liefern Daten"}, {"text": "Schnellste Tools", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Marktumfeld beeinflusst IT-Entscheidungen. b) Es ist immer vorhersehbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unvorhersehbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich beim Marktumfeld in der IT?', 5, '[{"text": "Technologische Entwicklungen", "correct": true, "because": "Formen Markt"}, {"text": "Kundenverhalten", "correct": true, "because": "Bestimmt Nachfrage"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich das Marktumfeld für eine IT-Firma analysiere?', 3, '[{"text": "Wettbewerber", "correct": false, "because": "Beeinflussen Markt"}, {"text": "Regulierungen", "correct": false, "because": "Setzen Rahmen"}, {"text": "Büromöbel", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Marktumfeld in der IT immer vorhersehbar?', 3, '[{"text": "Nein", "correct": true, "because": "Dynamisch und unsicher"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Marktumfeld nur wirtschaftliche Faktoren umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch technologisch, rechtlich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für die Analyse des Marktumfelds?', 4, '[{"text": "Externe Einflüsse", "correct": true, "because": "Bestimmen Rahmen"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]');
